import { useState } from 'react';
export function ProductQuantity({ name }) {
  const [quantity, setQuantity] = useState(1);
  return <section>
    <h2>{name}: {quantity}</h2>
    <button onClick={() => setQuantity(quantity + 1)}>+</button>
    <button onClick={() => setQuantity(1)}>Reset</button>
    <p>Sztuk: {quantity}</p>
  </section>;
}

import { useState } from 'react';
export function TicketSummary({ tickets }) {
  const [status, setStatus] = useState('ALL');
  const visible = tickets.filter(t => status === 'ALL' || t.status === status);
  const count = visible.length;
  return <section>
    <h2>Wyniki: {count}</h2>
    <button onClick={() => setStatus('ALL')}>Wszystkie</button>
    <button onClick={() => setStatus('OPEN')}>Otwarte</button>
    <p>Liczba widocznych: {count}</p>
  </section>;
}
// Dla OPEN, CLOSED, OPEN: start 3/3, po Otwarte 2/2, po Wszystkie 3/3.

